/* Trip planning, consent-based introductions, insights, and future concepts. */
'use strict';
AC.defaultTrip={city:'Dallas',start:'2026-11-10',end:'2026-11-12',industries:['Finance','Real estate'],goal:'Meet potential partners for our expansion into Texas',shortlist:[]};
AC.trip=()=>AC.state.trip||AC.defaultTrip;
AC.tripSteps=(n)=>`<div class="steps" aria-label="Trip planning progress">${['Plan your visit','Choose people','Start a conversation'].map((t,i)=>`<div class="step ${i===n?'active':''}" ${i===n?'aria-current="step"':''}><b>${i+1}</b><span>${t}</span></div>`).join('')}</div>`;
AC.renders.trips=()=>`${AC.title('A familiar face in a new city.','Build a thoughtful meeting plan before you pack your bag.',AC.link('trip-planner',AC.icon('plus')+' Plan a trip','btn primary'),'Trips')}<div class="split"><section class="panel">${AC.stateBlock(AC.state.trip?`<div class="pad"><div class="od-cluster"><span class="chip">${AC.icon('trip')}Upcoming trip</span><span class="meta">Private to you</span></div><h2 style="font-size:36px;margin-top:20px">${AC.esc(AC.state.trip.city)}</h2><p class="muted" style="margin-top:8px">${AC.state.trip.start} — ${AC.state.trip.end}</p><p style="margin-top:24px">${AC.esc(AC.state.trip.goal)}</p><div class="form-actions">${AC.link('trip-shortlist','View your shortlist','btn primary')}${AC.link('trip-planner','Edit trip','btn')}</div><p class="meta" style="margin-top:20px">${AC.state.trip.shortlist.length} alumni selected · No messages sent automatically</p></div>`:AC.empty('Where are you headed?','Find alumni in your destination, choose a few people worth meeting, and make time for a conversation.',AC.link('trip-planner','Plan your first trip','btn primary')),'No trips planned','Start with a city, your dates, and what you hope to accomplish.',AC.link('trip-planner','Plan a trip','btn primary'))}</section><aside class="right-rail stack"><section class="trip-callout"><div class="eyebrow">A little preparation. A warmer hello.</div><h2>Make the trip<br>more personal.</h2><p>Recommendations consider your destination, industries, and goal. Every draft is yours to review.</p></section><section class="panel pad"><h3>Respect their time</h3><p class="small muted" style="margin-top:12px">Start with a short, specific invitation. Choose a few relevant people rather than sending to everyone.</p></section></aside></div>`;
AC.renders['trip-planner']=()=>{let t=AC.trip();return `${AC.title('Make room for a good conversation.','Tell us where you’re going and what would make a meeting worthwhile.','','Trips / Plan a visit')}${AC.tripSteps(0)}<div class="split"><section class="panel pad"><div class="form-grid">${AC.select('Destination city','trip-city',['Dallas','Chicago','Austin','New York'],t.city)}<div></div>${AC.field('Arrival date','trip-start',t.start,'date')}${AC.field('Departure date','trip-end',t.end,'date')}</div><fieldset style="margin-top:24px"><legend>Industries you’d like to meet</legend><p class="meta" style="margin-top:8px">Choose one or more. You can refine your shortlist next.</p><div class="form-grid" style="margin-top:12px">${AC.sectors.map(s=>`<label class="checkbox"><input name="trip-industry" type="checkbox" value="${s}" ${t.industries.includes(s)?'checked':''}>${s}</label>`).join('')}</div></fieldset><div style="margin-top:24px">${AC.textarea('What’s your goal for this trip?','trip-goal',t.goal,'Be specific: a partnership, market perspective, or a career conversation.')}</div><p class="error-text" id="trip-error" hidden></p><div class="form-actions">${AC.btn('Find people to meet '+AC.icon('arrow'),'save-trip','primary')}${AC.link('trips','Cancel','btn quiet')}</div></section><aside class="right-rail stack"><section class="panel pad"><h2 class="rail-title">A shortlist, with reasons</h2><p class="small muted">We’ll suggest alumni whose location and work fit your trip. Shared experiences and introduction paths appear alongside each suggestion.</p><div class="divider"></div><p class="small muted">Your trip is private. Nobody is notified unless you choose to send a message.</p></section></aside></div>`};
AC.handlers['save-trip']=()=>{let city=document.getElementById('trip-city').value,start=document.getElementById('trip-start').value,end=document.getElementById('trip-end').value,goal=document.getElementById('trip-goal').value.trim(),industries=[...document.querySelectorAll('[name=trip-industry]:checked')].map(i=>i.value),err=document.getElementById('trip-error');if(!start||!end||end<start||!goal||!industries.length){err.hidden=false;err.textContent='Add arrival and departure dates in order, at least one industry, and a short meeting goal.';err.tabIndex=-1;err.focus();return}AC.state.trip={city,start,end,goal,industries,shortlist:AC.state.trip?.city===city?AC.state.trip.shortlist:[]};AC.persist();AC.go('trip-shortlist')};
AC.renders['trip-shortlist']=()=>{let t=AC.trip(),people=AC.visiblePeople().filter(p=>p.city===t.city&&t.industries.includes(p.industry));return `${AC.title('A few people. Better conversations.',`${t.city} · ${t.start} to ${t.end}`,AC.link('trip-planner','Edit trip','btn'),'Trips / Your shortlist')}${AC.tripSteps(1)}<div class="split"><section class="stack"><div class="notice">${AC.icon('info')}<div><strong>Your goal</strong><p>${AC.esc(t.goal)}</p></div></div><div class="panel">${AC.stateBlock(people.length?people.map(p=>`<article>${AC.person(p)}<div class="pad" style="padding-top:0"><span class="chip ai">AI-generated relevance</span><p class="small muted" style="margin:12px 0 16px">${p.why}</p>${AC.btn((t.shortlist.includes(p.id)?AC.icon('check')+' Selected':'Add to shortlist'),'shortlist','',`data-id="${p.id}" aria-pressed="${t.shortlist.includes(p.id)}"`)}</div></article>`).join(''):AC.empty('No matches for this visit yet','Try another industry or adjust your destination. We won’t add unrelated people to fill your list.',AC.link('trip-planner','Edit trip','btn primary')),'No matches for this visit','Try another industry or a different destination.',AC.link('trip-planner','Edit trip','btn primary'))}</div></section><aside class="right-rail stack"><section class="panel pad"><h2 class="rail-title">Your meeting shortlist</h2><div id="shortlist-summary">${AC.shortlistSummary()}</div></section><section class="panel pad"><h3>One conversation at a time</h3><p class="small muted" style="margin-top:12px">Review and personalize each message. A shortlist doesn’t notify its members or guarantee availability.</p></section></aside></div>`};
AC.shortlistSummary=()=>{let t=AC.trip();return t.shortlist.length?`<div class="detail-list">${t.shortlist.map(id=>{let p=AC.byId(id);return `<div class="detail-row"><strong class="small">${p.name}</strong><span class="meta">${p.specialty}</span>${AC.link('outreach','Draft an invitation '+AC.icon('arrow'),'btn quiet','?id='+id+'&trip=1')}</div>`}).join('')}</div><p class="meta" style="margin-top:16px">${t.shortlist.length} selected · Messages are reviewed individually</p>`:'<p class="small muted">Add a few relevant alumni. Your shortlist stays private until you choose to reach out.</p>'};
AC.handlers.shortlist=b=>{if(!AC.state.trip)AC.state.trip=JSON.parse(JSON.stringify(AC.defaultTrip));let t=AC.state.trip,id=b.dataset.id;t.shortlist=t.shortlist.includes(id)?t.shortlist.filter(x=>x!==id):[...t.shortlist,id];AC.persist();b.innerHTML=t.shortlist.includes(id)?AC.icon('check')+' Selected':'Add to shortlist';b.setAttribute('aria-pressed',String(t.shortlist.includes(id)));document.getElementById('shortlist-summary').innerHTML=AC.shortlistSummary()};
AC.renders.outreach=()=>{let p=AC.byId(AC.params.get('id')||'p5'),t=AC.trip(),isTrip=AC.params.get('trip')==='1';let defaultDraft=`Hi ${p.name.split(' ')[0]},\n\nI’m Alex, a fellow Wisconsin alum (class of 2008). ${isTrip?`I’ll be in ${t.city} from ${t.start} to ${t.end}.`:`I came across your work in ${p.specialty.toLowerCase()}.`}\n\n${isTrip?t.goal+'.':'I’m interested in learning more about your work and exploring where our professional interests overlap.'} Would you be open to a brief conversation${isTrip?' while I’m in town':''}?\n\nNo pressure if the timing isn’t right. On, Wisconsin!\nAlex`;let draft=AC.state.drafts?.[p.id]||defaultDraft;return `${AC.title('A thoughtful first hello.',`To ${p.name} · ${p.title} at ${p.company}`,'','Relationships / Outreach')}${isTrip?AC.tripSteps(2):''}<div class="split"><section class="panel pad"><div class="section-head"><h2>Your message</h2><span class="chip ai">AI-drafted · Editable</span></div>${AC.field('Subject','outreach-subject',AC.state.subjects?.[p.id]||(isTrip?`Fellow Wisconsin alum visiting ${t.city}`:'A hello from a fellow Wisconsin alum'))}<div style="margin-top:24px">${AC.textarea('Message','outreach-body',draft,'Review the details and make this sound like you before sending.')}</div><div class="notice" style="margin-top:24px">${AC.icon('lock')}<p>Your first message goes through an email relay. Your sender address remains hidden until the recipient replies. No real email is sent in this prototype.</p></div><div id="outreach-feedback" style="margin-top:24px"></div><div class="form-actions">${AC.btn('Send via private relay','send-outreach','primary',`data-id="${p.id}"`)}${AC.btn('Save draft','save-draft','',`data-id="${p.id}"`)}</div><p class="error-text" id="outreach-error" hidden></p></section><aside class="right-rail stack"><section class="panel pad"><div class="od-row">${AC.avatar(p)}<div class="od-field"><h3>${p.name}</h3><span class="meta">Wisconsin ’${String(p.year).slice(-2)}</span></div></div><div class="divider"></div><span class="chip ai">Why this person</span><p class="small muted" style="margin-top:12px">${p.why}</p>${p.path?`<div class="form-actions">${AC.link('introductions','Ask for a warm introduction','btn quiet','?id='+p.id)}</div>`:''}</section><section class="panel pad"><h3>Keep it easy to answer</h3><p class="small muted" style="margin-top:12px">Say why you’re reaching out, ask for something specific, and leave room for a gracious no.</p></section></aside></div>`};
AC.saveDraft=id=>{AC.state.drafts||={};AC.state.subjects||={};AC.state.drafts[id]=document.getElementById('outreach-body').value;AC.state.subjects[id]=document.getElementById('outreach-subject').value;AC.persist()};
AC.handlers['save-draft']=b=>{AC.saveDraft(b.dataset.id);AC.toast('Draft saved. No message has been sent.')};
AC.handlers['send-outreach']=b=>{let subj=document.getElementById('outreach-subject').value.trim(),body=document.getElementById('outreach-body').value.trim(),err=document.getElementById('outreach-error');if(!subj||body.length<20){err.hidden=false;err.textContent='Add a subject and a message of at least 20 characters.';return}err.hidden=true;AC.saveDraft(b.dataset.id);AC.modal('Ready to send?',`<p class="small muted">This prototype will record a simulated relay message. No external email is sent.</p><div class="detail-row"><strong>To ${AC.byId(b.dataset.id).name}</strong><span class="small">${AC.esc(subj)}</span></div><p class="small" style="white-space:pre-wrap;margin-top:16px">${AC.esc(body)}</p><div class="form-actions">${AC.btn('Simulate sending','confirm-outreach','primary',`data-id="${b.dataset.id}"`)}${AC.btn('Keep editing','close-dialog')}</div>`,b)};
AC.handlers['confirm-outreach']=b=>{AC.state.outreach||={};AC.state.outreach[b.dataset.id]={subject:AC.state.subjects[b.dataset.id],body:AC.state.drafts[b.dataset.id],at:new Date().toISOString()};AC.persist();AC.close();document.getElementById('outreach-feedback').innerHTML=AC.notice('Message recorded as sent in this prototype. The recipient can choose whether to reply. Your address is still hidden.','success')+`<div class="form-actions">${AC.link('meeting','Prepare a meeting invitation','btn','?id='+b.dataset.id)}</div>`;let btn=document.querySelector('[data-action=send-outreach]');btn.disabled=true;btn.textContent='Message recorded'};
AC.renders.meeting=()=>{let p=AC.byId(AC.params.get('id')||'p5');return `${AC.title('Make time for a conversation.',`Prepare a calendar invitation for ${p.name}. Confirm availability with them before sending.`,'','Trips / Meeting invitation')}<section class="panel pad narrow">${AC.notice('This creates a local .ics calendar file. It does not book a time or send an invitation automatically.')}<div class="form-grid" style="margin-top:24px">${AC.field('Meeting title','meeting-title','Coffee with '+p.name)}${AC.field('Date','meeting-date',AC.trip().start,'date')}${AC.field('Start time','meeting-time','10:00','time')}${AC.select('Duration','meeting-duration',['30 minutes','45 minutes','60 minutes'])}${AC.select('Time zone','meeting-zone',['America/Chicago','America/New_York','America/Denver','America/Los_Angeles'],'America/Chicago')}${AC.field('Location or meeting link','meeting-location','To be agreed')}</div><div class="form-actions">${AC.btn('Download calendar invitation','calendar','primary',`data-id="${p.id}"`)}</div><p class="error-text" id="meeting-error" hidden></p><div id="meeting-feedback" style="margin-top:24px"></div></section>`};
AC.download=(name,text,type)=>{let url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000)};
AC.handlers.calendar=b=>{let get=id=>document.getElementById('meeting-'+id).value,title=get('title'),date=get('date'),time=get('time'),loc=get('location'),zone=get('zone'),duration=parseInt(get('duration')),err=document.getElementById('meeting-error');if(!title.trim()||!date||!time){err.hidden=false;err.textContent='Add a meeting title, date, and start time.';return}err.hidden=true;let start=date.replaceAll('-','')+'T'+time.replace(':','')+'00',dt=new Date(date+'T'+time),end=new Date(dt.getTime()+duration*60000),pad=n=>String(n).padStart(2,'0'),endstamp=end.getFullYear()+pad(end.getMonth()+1)+pad(end.getDate())+'T'+pad(end.getHours())+pad(end.getMinutes())+'00',escape=s=>s.replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;'),ics=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Alumni Connect//Prototype//EN','BEGIN:VEVENT','UID:'+crypto.randomUUID()+'@example.com','DTSTAMP:'+new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,''),'DTSTART;TZID='+zone+':'+start,'DTEND;TZID='+zone+':'+endstamp,'SUMMARY:'+escape(title),'LOCATION:'+escape(loc),'DESCRIPTION:Confirm this time with your contact before sending. Fictional prototype invitation.','STATUS:TENTATIVE','END:VEVENT','END:VCALENDAR'].join('\r\n');AC.download('alumni-connect-meeting.ics',ics,'text/calendar;charset=utf-8');AC.state.interactions.unshift({person:AC.byId(b.dataset.id).name,type:'Meeting invitation prepared',note:title+' · '+date+' '+time+' '+zone,date});AC.persist();document.getElementById('meeting-feedback').innerHTML=AC.notice('Calendar file prepared. Import it into your calendar and confirm the time with your contact.','success')};
AC.renders.introductions=()=>{let p=AC.byId(AC.params.get('id')||AC.state.introTarget||'p2'),connector=p.path||'Jordan Ellis',stage=AC.state.introStage;return `${AC.title('Start with someone you both know.','A warm introduction takes two yeses. Nobody is connected without their consent.','','Relationships / Introductions')}${AC.relationshipTabs()}<div class="split"><section class="panel pad"><div class="network-graphic" aria-label="You to connector to recipient"><span class="avatar">AM</span><span class="network-line"></span><span class="avatar">${connector.split(' ').map(x=>x[0]).join('')}</span><span class="network-line"></span>${AC.avatar(p)}</div><h2>You → ${connector} → ${p.name}</h2><p class="small muted" style="margin:16px 0 24px">${stage==='none'?'Ask your mutual connection whether they’d be comfortable introducing you.':stage==='requested'?'Your request is waiting for the connector’s decision.':stage==='connector-agreed'?'The connector agreed. The recipient is now being asked privately.':stage==='accepted'?'Both people agreed. Your introduction is ready.':'This introduction did not proceed. No contact details were shared.'}</p><div class="steps"><div class="step ${stage==='requested'?'active':''}"><b>1</b><span>Connector agrees</span></div><div class="step ${stage==='connector-agreed'?'active':''}"><b>2</b><span>Recipient agrees</span></div><div class="step ${stage==='accepted'?'active':''}"><b>3</b><span>Introduction made</span></div></div>${stage==='none'?`${AC.textarea('Why would you like to meet?','intro-reason',AC.state.introReason||`I’d value ${p.name.split(' ')[0]}’s perspective on ${p.specialty.toLowerCase()} and would love to explore whether our work overlaps.`,'Your connector can review this before deciding.')}<div class="form-actions">${AC.btn('Ask '+connector.split(' ')[0]+' for an introduction','request-intro','primary',`data-id="${p.id}"`)}</div>`:stage==='accepted'?AC.notice('Introduction accepted by both parties. You can now start a relay conversation.','success')+`<div class="form-actions">${AC.link('outreach','Write your introduction message','btn primary','?id='+p.id)}</div>`:AC.notice(stage==='requested'?'Waiting for connector · No details have been shared with the recipient.':stage==='connector-agreed'?'Waiting for recipient · Your contact details remain private.':'Request closed · You can continue building connections elsewhere.')}</section><aside class="right-rail stack"><section class="panel pad"><h2 class="rail-title">No surprise introductions</h2><div class="detail-list"><div class="detail-row"><strong class="small">First, your connector chooses</strong><p class="small muted">They can decline without an explanation.</p></div><div class="detail-row"><strong class="small">Then, the recipient chooses</strong><p class="small muted">They see your context before agreeing.</p></div><div class="detail-row"><strong class="small">Only then, a conversation</strong><p class="small muted">Contact visibility remains under each member’s control.</p></div></div></section></aside></div>`};
AC.handlers['request-intro']=b=>{let reason=document.getElementById('intro-reason').value.trim();if(reason.length<20){AC.toast('Add a little more context so your connector can make an informed decision.');return}AC.state.introTarget=b.dataset.id;AC.state.introReason=reason;AC.state.introStage='requested';AC.persist();AC.render();AC.toast('Introduction request recorded. No external message was sent.')};
AC.renders['introduction-review']=()=>{let p=AC.byId(AC.state.introTarget||'p2'),pending=AC.state.introStage==='requested';return `${AC.title('Would you be comfortable connecting them?','Connector view · A private request from Alex Morgan.','','Relationships / Introduction request')}<section class="panel pad narrow"><div class="od-cluster"><span class="chip">Connector’s consent</span><span class="chip ${pending?'':'subtle'}">${pending?'Awaiting your decision':AC.state.introStage==='none'?'No request yet':'Decision recorded'}</span></div><h2 style="margin-top:24px">Alex Morgan would like to meet ${p.name}.</h2><p class="small muted" style="margin-top:16px">${AC.esc(AC.state.introReason||'A request will appear here after a member asks you for an introduction.')}</p><div class="divider"></div><p class="small muted">Agreeing sends the recipient a private opt-in request. It doesn’t share their contact details or create a conversation yet.</p><div class="form-actions">${AC.btn('I’m happy to introduce them','connector-accept','primary',pending?'':'disabled')}${AC.btn('Decline quietly','connector-decline','',pending?'':'disabled')}</div><p class="meta" style="margin-top:16px">A decline closes the request without asking for a reason.</p></section>`};
AC.handlers['connector-accept']=()=>{if(AC.state.introStage!=='requested')return;AC.state.introStage='connector-agreed';AC.persist();AC.render();AC.toast('Your agreement is recorded. The recipient must also opt in.')};
AC.handlers['connector-decline']=()=>{if(AC.state.introStage!=='requested')return;AC.state.introStage='declined';AC.persist();AC.render();AC.toast('Request closed. No introduction was made.')};
AC.renders['introduction-response']=()=>{let p=AC.byId(AC.state.introTarget||'p2'),pending=AC.state.introStage==='connector-agreed';return `${AC.title('A familiar connection has someone in mind.','Recipient view · You decide whether to accept.','','Relationships / Introduction invitation')}<section class="panel pad narrow"><span class="chip">Recipient’s consent</span><h2 style="margin-top:24px">${p.path||'Jordan Ellis'} would like to introduce you to Alex Morgan.</h2><p class="small muted" style="margin-top:16px">Wisconsin ’2008 · Director, Strategic Partnerships at Northfield Advisory · Chicago, IL</p><div class="notice" style="margin-top:24px"><div><strong>Why Alex would like to connect</strong><p>${AC.esc(AC.state.introReason||'The request context will appear after the connector agrees.')}</p></div></div><p class="small muted" style="margin-top:24px">Accepting starts an introduction through the relay. Your contact settings remain in place. Declining shares no contact details.</p><div class="form-actions">${AC.btn('Accept introduction','recipient-accept','primary',pending?'':'disabled')}${AC.btn('Not right now','recipient-decline','',pending?'':'disabled')}</div><div style="margin-top:24px">${AC.notice(AC.state.introStage==='accepted'?'Accepted by both sides. A relay conversation can now begin.':AC.state.introStage==='declined'?'Request closed. No details were shared.':pending?'The connector has agreed. The decision is now yours.':'This invitation is not awaiting a recipient decision.')}</div></section>`};
AC.handlers['recipient-accept']=()=>{if(AC.state.introStage!=='connector-agreed')return;AC.state.introStage='accepted';AC.state.interactions.unshift({person:AC.byId(AC.state.introTarget).name,type:'Warm introduction',date:new Date().toISOString().slice(0,10),note:'Both connector and recipient opted in.'});AC.persist();AC.render();AC.toast('Introduction accepted. Both people have opted in.')};
AC.handlers['recipient-decline']=()=>{if(AC.state.introStage!=='connector-agreed')return;AC.state.introStage='declined';AC.persist();AC.render();AC.toast('Invitation declined. No contact details were shared.')};
AC.renders.insights=()=>`${AC.title('See where the network comes together.','Explore concentrations by market and industry, with every count labeled by its source.','','Network insights')}<div class="filter-row" style="margin:0 0 24px"><label class="field small">Industry<select id="insight-industry">${AC.options(['All industries',...AC.sectors])}</select></label><label class="field small">Market<select id="insight-city">${AC.options(['All markets','Chicago','Dallas','Austin','New York'])}</select></label></div><div id="insight-content"></div>`;
AC.insights=()=>{let industry=document.getElementById('insight-industry').value,city=document.getElementById('insight-city').value,people=AC.visiblePeople().filter(p=>(industry==='All industries'||p.industry===industry)&&(city==='All markets'||p.city===city)),confirmed=people.filter(p=>p.confirmed).length,unconfirmed=people.length-confirmed;let chart=(key,title)=>`<section class="panel pad"><h2>${title}</h2><p class="meta" style="margin-top:8px">Sample records, not estimated alumni population</p>${[...new Set(people.map(p=>p[key]))].map(v=>{let ps=people.filter(p=>p[key]===v),c=ps.filter(p=>p.confirmed).length,u=ps.length-c;return `<div class="bar-row"><span>${v}</span><div class="bar-track" role="img" aria-label="${v}: ${c} confirmed and ${u} unconfirmed records"><span class="bar-confirmed" style="width:${c/Math.max(people.length,1)*100}%"></span><span class="bar-unconfirmed" style="width:${u/Math.max(people.length,1)*100}%"></span></div><span class="mono">${ps.length}</span></div><p class="meta" style="margin:4px 0 0 0">${c} confirmed · ${u} unconfirmed</p>`}).join('')}<div class="legend"><span><i></i>Confirmed</span><span><i class="est"></i>Unconfirmed records</span></div></section>`;let html=people.length?`<section class="panel" style="margin-bottom:24px"><div class="summary-strip"><div class="od-stat"><strong>${confirmed}</strong><span>Confirmed records</span></div><div class="od-stat"><strong>${unconfirmed}</strong><span>Unconfirmed records</span></div><div class="od-stat"><strong>—</strong><span>Population estimate unavailable</span></div></div><p class="meta pad">Fictional sample dataset · ${people.length} matching records · Figures are not claims about UW–Madison’s alumni population.</p></section><div class="form-grid">${chart('city','By market')}${chart('industry','By industry')}</div><section class="notice" style="margin-top:24px">${AC.icon('info')}<div><strong>Use concentration as a starting point.</strong><p>For event planning, combine confirmed participation, member interest, and travel access. Counts alone do not establish demand.</p><div class="form-actions">${AC.link('events','Explore city events','btn quiet')}</div></div></section>`:AC.empty('No records for this combination','Choose a different market or industry. Zero records does not mean there are no alumni in that market.');document.getElementById('insight-content').innerHTML=AC.stateBlock(html,'No records for these filters','Try a different market or industry.')};
AC.renders.mentorship=()=>`${AC.title('A conversation can change a career.','Find an alumnus whose experience fits the advice you’re looking for.','','Explore / Mentorship concept')}<section class="notice" style="margin-bottom:24px">${AC.icon('info')}<p>Future feature concept · Matching suggestions are illustrative. Availability and expectations must be agreed with each mentor.</p></section><section class="panel pad" style="margin-bottom:24px"><div class="form-grid">${AC.select('What would you like help with?','mentor-topic',['Career direction','Moving into leadership','Starting a business','Entering technology'])}${AC.select('Preferred market','mentor-city',['Any market','Chicago','Austin'])}</div><div class="form-actions">${AC.btn('Find mentoring conversations','match-mentors','primary')}</div></section><section class="panel" id="mentor-results">${AC.personList(AC.visiblePeople().filter(p=>p.open.includes('Mentoring')))}</section>`;
AC.handlers['match-mentors']=()=>{let city=document.getElementById('mentor-city').value,topic=document.getElementById('mentor-topic').value;let ps=AC.visiblePeople().filter(p=>p.open.includes('Mentoring')&&(city==='Any market'||p.city===city)).sort((a,b)=>Number(b.industry===(topic==='Entering technology'?'Technology':topic==='Starting a business'?'Healthcare':'Finance'))-Number(a.industry===(topic==='Entering technology'?'Technology':topic==='Starting a business'?'Healthcare':'Finance')));document.getElementById('mentor-results').innerHTML=AC.stateBlock(ps.length?AC.personList(ps):AC.empty('No available matches','Try a different market.'));AC.toast('Mentors reordered for '+topic.toLowerCase())};
AC.businesses=[{name:'Commonfield Health',field:'Healthcare',city:'Austin',owner:'Priya Nair',id:'p3',copy:'Health technology for community care teams.'},{name:'Elmstone Realty',field:'Real estate',city:'Dallas',owner:'Rachel Foster',id:'p10',copy:'Commercial property advice for growing regional businesses.'},{name:'Redwood Property Group',field:'Real estate',city:'Chicago',owner:'Michael Rivera',id:'p2',copy:'Commercial real estate investment and market advisory.'}];
AC.renders.businesses=()=>`${AC.title('Find a business with a Wisconsin connection.','An alumni business directory, designed for relevant discovery.','','Explore / Business directory concept')}${AC.notice('Future feature concept · All businesses below are fictional. Alumni ownership is member-reported, not a university endorsement.')}<div class="form-grid" style="margin:24px 0">${AC.field('Search businesses','business-search','','search')}${AC.select('Industry','business-industry',['All industries','Healthcare','Real estate'])}</div><div class="stack" id="business-results">${AC.businessCards(AC.businesses)}</div>`;
AC.businessCards=bs=>bs.length?bs.map(b=>`<section class="panel pad"><div class="section-head"><div><span class="eyebrow accent">${b.field} · ${b.city}</span><h2 style="margin-top:12px">${b.name}</h2></div><span class="chip">Member-reported</span></div><p class="small muted">${b.copy}</p><div class="form-actions">${AC.link('profile','Meet '+b.owner,'btn','?id='+b.id)}</div></section>`).join(''):AC.empty('No businesses match','Clear the search or choose another industry.');
AC.events=[{id:'e1',day:'12',month:'NOV',title:'Dallas alumni coffee hour',city:'Dallas',date:'2026-11-12',location:'Fictional location · Juniper House',copy:'A small-group morning for visiting and local alumni.'},{id:'e2',day:'19',month:'NOV',title:'Chicago professional connections',city:'Chicago',date:'2026-11-19',location:'Fictional location · Northfield Hall',copy:'Meet alumni across industries in your home market.'},{id:'e3',day:'03',month:'DEC',title:'Austin technology roundtable',city:'Austin',date:'2026-12-03',location:'Fictional location · Fieldstone Studio',copy:'A focused discussion about building teams and mentoring.'}];
AC.renders.events=()=>`${AC.title('Good conversations happen locally.','Find a reason to gather with alumni in your city—or the next one you visit.','','Explore / Events concept')}${AC.notice('Future feature concept · Fictional events for design purposes. RSVPs are stored locally; no organizer is notified.')}<div style="max-width:320px;margin:24px 0">${AC.select('City','event-city',['All cities','Dallas','Chicago','Austin'])}</div><div class="stack" id="event-results">${AC.eventCards(AC.events)}</div>`;
AC.eventCards=es=>es.length?es.map(e=>`<section class="panel pad"><div class="od-row-top" style="gap:24px"><div class="event-date"><span>${e.month}</span><strong>${e.day}</strong></div><div class="od-fill"><div class="eyebrow accent">${e.city}</div><h2 style="margin-top:8px">${e.title}</h2><p class="small muted" style="margin-top:12px">${e.copy}</p><p class="meta" style="margin-top:8px">${e.date} · ${e.location}</p><div class="form-actions">${AC.btn(AC.state.rsvps.includes(e.id)?'Cancel RSVP':'RSVP privately','rsvp',AC.state.rsvps.includes(e.id)?'':'primary',`data-id="${e.id}"`)}</div>${AC.state.rsvps.includes(e.id)?'<p class="small" style="color:var(--success);margin-top:12px">RSVP recorded in this prototype.</p>':''}</div></div></section>`).join(''):AC.empty('No events in this city yet','Choose another city or return later.');
AC.handlers.rsvp=b=>{let id=b.dataset.id;AC.state.rsvps=AC.state.rsvps.includes(id)?AC.state.rsvps.filter(v=>v!==id):[...AC.state.rsvps,id];AC.persist();let city=document.getElementById('event-city').value;document.getElementById('event-results').innerHTML=AC.eventCards(AC.events.filter(e=>city==='All cities'||e.city===city));AC.toast(AC.state.rsvps.includes(id)?'RSVP recorded locally':'RSVP canceled')};
AC.jobs=[{id:'j1',title:'Partnerships Director',company:'Commonfield Health',city:'Austin',industry:'Healthcare',contact:'p3'},{id:'j2',title:'Senior Software Engineer',company:'Fieldstone Software',city:'Austin',industry:'Technology',contact:'p7'},{id:'j3',title:'Real Estate Associate',company:'Elmstone Realty',city:'Dallas',industry:'Real estate',contact:'p10'}];
AC.renders.jobs=()=>`${AC.title('Your next chapter, through a shared connection.','Explore roles and ask thoughtfully about a referral.','','Explore / Jobs & referrals concept')}${AC.notice('Future feature concept · All roles and employers are fictional. Asking about a referral doesn’t guarantee one.')}<div class="form-grid" style="margin:24px 0">${AC.field('Search roles','job-search','','search')}${AC.select('Industry','job-industry',['All industries','Healthcare','Technology','Real estate'])}</div><div class="stack" id="job-results">${AC.jobCards(AC.jobs)}</div>`;
AC.jobCards=js=>js.length?js.map(j=>`<section class="panel pad"><div class="section-head"><div><span class="eyebrow accent">${j.industry} · ${j.city}</span><h2 style="margin-top:12px">${j.title}</h2><p class="small muted">${j.company}</p></div><span class="chip">Sample role</span></div><p class="small muted">${AC.byId(j.contact).name} works here and is open to professional conversations.</p><div class="form-actions">${AC.btn('Ask about a referral','referral','primary',`data-id="${j.id}"`)}${AC.link('profile','View alumni connection','btn','?id='+j.contact)}</div></section>`).join(''):AC.empty('No roles match','Try another industry or search term.');
AC.handlers.referral=b=>{let job=AC.jobs.find(j=>j.id===b.dataset.id);AC.modal('Ask about '+job.title,`${AC.textarea('Message to '+AC.byId(job.contact).name,'referral-message',`Hi ${AC.byId(job.contact).name.split(' ')[0]}, I’m a fellow Wisconsin alum interested in the ${job.title} role. Would you be open to sharing your perspective before I apply?`,'Editable sample message · No external message is sent.')}<div class="form-actions">${AC.btn('Save referral request','save-referral','primary',`data-id="${job.id}"`)}</div>`,b)};
AC.handlers['save-referral']=b=>{let message=document.getElementById('referral-message').value.trim();if(message.length<20){AC.toast('Add a short message explaining your interest.');return}AC.state.referrals||=[];AC.state.referrals.push({job:b.dataset.id,message});AC.persist();AC.close();AC.toast('Referral request saved locally. No message sent.')};
